package middlewares_test

import (
	"bytes"
	"errors"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"testing"

	"github.com/gin-gonic/gin"
	"github.com/mbashem/cftracker/backend/internal/auth"
	"github.com/mbashem/cftracker/backend/internal/middlewares"
)

const (
	testOAuthCode     = "example-authorization-value"
	testOAuthState    = "example-state-value"
	testPrivateHeader = "example-private-header"
	testOAuthQuery    = "code=" + testOAuthCode + "&state=" + testOAuthState
)

// Generated by Codex and not thoroughly checked for correctness.
func TestRequestLoggerPreservesParametersWithoutLoggingThem(t *testing.T) {
	gin.SetMode(gin.TestMode)
	for _, testCase := range []struct {
		name, method, path, query string
		status                    int
	}{
		{"successful callback", http.MethodGet, "/auth/github/callback", testOAuthQuery, http.StatusOK},
		{"rejected callback alias", http.MethodGet, "/api/auth/github/callback", testOAuthQuery, http.StatusBadRequest},
		{"duplicate and encoded query parameters", http.MethodGet, "/api/auth/github/callback", testOAuthQuery + "&%63ode=another-private-value&state=another-state", http.StatusBadRequest},
		{"other routes also omit queries", http.MethodGet, "/api/lists", testOAuthQuery, http.StatusForbidden},
		{"request without query", http.MethodPost, "/api/lists", "", http.StatusCreated},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			var output bytes.Buffer
			router := gin.New()
			router.Use(middlewares.RequestLogger(&output), middlewares.Recovery(&output))
			router.Handle(testCase.method, testCase.path, func(ctx *gin.Context) {
				if ctx.Request.URL.RawQuery != testCase.query {
					t.Fatal("logger changed request query")
				}
				if testCase.query != "" && (ctx.Query("code") != testOAuthCode || ctx.Query("state") != testOAuthState) {
					t.Fatal("OAuth handler cannot read original parameters")
				}
				// Raw handler errors can themselves contain sensitive request URLs.
				_ = ctx.Error(errors.New(testOAuthQuery))
				ctx.Status(testCase.status)
			})
			request := httptest.NewRequest(testCase.method, testCase.path+"?"+testCase.query, nil)
			request.RemoteAddr = "192.0.2.1:1234"
			request.Header.Set("Authorization", testPrivateHeader)
			response := httptest.NewRecorder()
			router.ServeHTTP(response, request)
			if response.Code != testCase.status {
				t.Fatalf("status=%d, want %d", response.Code, testCase.status)
			}
			log := output.String()
			for _, want := range []string{"[GIN]", testCase.method, testCase.path, strconv.Itoa(testCase.status), "192.0.2.1", " | "} {
				if !strings.Contains(log, want) {
					t.Fatalf("missing %q in log: %s", want, log)
				}
			}
			assertNoRequestSecrets(t, log)
			if strings.Contains(log, testCase.path+"?") {
				t.Fatal("access log contains a query string")
			}
			if strings.Count(log, "\n") != 1 {
				t.Fatalf("expected one access record, got %q", log)
			}
		})
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestRegisteredOAuthCallbacksDoNotLogRejectedParameters(t *testing.T) {
	gin.SetMode(gin.TestMode)
	for _, path := range []string{"/auth/github/callback", "/api/auth/github/callback"} {
		t.Run(path, func(t *testing.T) {
			var output bytes.Buffer
			router := gin.New()
			router.Use(middlewares.RequestLogger(&output), middlewares.Recovery(&output))
			auth.RegisterRoutes(router, auth.NewAuthHandler(nil, nil))
			response := httptest.NewRecorder()
			// Missing OAuth cookie is rejected before any provider/database call.
			router.ServeHTTP(response, httptest.NewRequest(http.MethodGet, path+"?"+testOAuthQuery, nil))
			if response.Code != http.StatusBadRequest {
				t.Fatalf("status=%d", response.Code)
			}
			assertNoRequestSecrets(t, output.String())
			if !strings.Contains(output.String(), path) {
				t.Fatal("callback request was not logged")
			}
		})
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestRecoveryDoesNotDumpSecretsInDebugOrReleaseModes(t *testing.T) {
	for _, mode := range []string{gin.DebugMode, gin.ReleaseMode} {
		t.Run(mode, func(t *testing.T) {
			gin.SetMode(mode)
			t.Cleanup(func() { gin.SetMode(gin.TestMode) })
			var output bytes.Buffer
			router := gin.New()
			router.Use(middlewares.RequestLogger(&output), middlewares.Recovery(&output))
			router.GET("/api/auth/github/callback", func(*gin.Context) { panic(testOAuthQuery) })
			request := httptest.NewRequest(http.MethodGet, "/api/auth/github/callback?"+testOAuthQuery, nil)
			request.Header.Set("Cookie", "cftracker_github_oauth_state="+testOAuthState)
			request.Header.Set("Authorization", testPrivateHeader)
			response := httptest.NewRecorder()
			router.ServeHTTP(response, request)
			if response.Code != http.StatusInternalServerError {
				t.Fatalf("panic status=%d", response.Code)
			}
			log := output.String()
			assertNoRequestSecrets(t, log)
			for _, want := range []string{"[Recovery]", "panic_type=string", "goroutine", "[GIN]", "500"} {
				if !strings.Contains(log, want) {
					t.Fatalf("missing diagnostic %q", want)
				}
			}
		})
	}
}

func assertNoRequestSecrets(t *testing.T, log string) {
	t.Helper()
	for _, secret := range []string{testOAuthCode, testOAuthState, testPrivateHeader, "another-private-value", "another-state", "code=", "state="} {
		if strings.Contains(log, secret) {
			t.Fatalf("request secret %q leaked in log", secret)
		}
	}
}
